import { IngestPipeline } from "@514labs/moose-lib";

export interface UserActivity {
  eventId: string;
  eventTs: Date;
  userId: string;
  action: string;
  durationMs: number; // Will default null values to 0 during ingestion
}

export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["userId", "eventTs"] // Order by user first for user-based queries, then by time
  },
  stream: true,
  ingestApi: true,
});

import { MaterializedView } from "@514labs/moose-lib";
import { UserActivity } from "../ingest/UserActivity";

export interface DailySummary {
  date: Date;
  userId: string;
  eventCount: number;
  totalDurationMs: number;
}

export const DailySummaryView = new MaterializedView<DailySummary>("DailySummary", {
  sourceTable: "UserActivity",
  select: `
    SELECT
      toDate(eventTs) as date,
      userId,
      count() as eventCount,
      sum(coalesce(durationMs, 0)) as totalDurationMs
    FROM currentDatabase().UserActivity
    GROUP BY date, userId
  `,
  primaryKey: ["date", "userId"]
});

