awk -F',' 'BEGIN {OFS=","} {
  if (NF == 4 || $5 == "") {
    # Missing or empty duration, set to 0
    print $1, $2, $3, $4, 0
  } else {
    # Duration is present
    print $0
  }
}' /data/samples/user_activity_sample.csv | tail -n +2 > /tmp/processed_user_activity.csv
